#!/usr/bin/env python3
"""M24.4b -- proves the root-caused fix: inject the shim's HELLO into uart1's RX path via
Renode's own `WriteChar` monitor primitive (proven to work in
uart1_writechar_injection_probe_v2.py) instead of relying on CreateServerSocketTerminal's inbound
direction (proven NOT to work in uart_tcp_single_byte_probe.py and uart_pty_terminal_probe.py),
while continuing to read the guest's own UART1 output through the already-proven-working outbound
half of CreateServerSocketTerminal. If IO_LOCKSTEP's `do_handshake()` succeeds, the guest replies
with its own HELLO frame on the same bytes, and UART0's log stops showing
"lockstep-local handshake failed" -- instead progressing to `handle_bind()` (which blocks waiting
for a BIND frame this test does not send, so the app should sit there, not exit).
"""
import re
import socket
import subprocess
import sys
import time

UART1_BASE = 0xFF010000
REG_CONTROL = UART1_BASE + 0x00
CONTROL_RXEN = 1 << 2

HELLO_MAGIC = b"AVL1"
PROTOCOL_VERSION = 1

HEX_RE = re.compile(r"0x[0-9A-Fa-f]{8}")
ANSI_RE = re.compile(rb"\x1b\[[0-9;]*m")

RENODE = ("/Users/probe/code/AltaVista/third_party/renode/renode-1.16.1-osx-arm64/"
          "Renode.app/Contents/MacOS/renode")
RESC = "/Users/probe/code/AltaVista/third_party/renode/M24_4b/uart1_register_probe.resc"


def clean(raw: bytes) -> str:
    return ANSI_RE.sub(b"", raw).decode(errors="replace").strip()


def build_hello_frame():
    payload = HELLO_MAGIC + PROTOCOL_VERSION.to_bytes(2, "little")
    length = 1 + len(payload)
    return length.to_bytes(4, "little") + bytes([0x01]) + payload


class MonitorClient:
    def __init__(self, sock):
        self.sock = sock

    def send(self, line: str):
        self.sock.sendall((line + "\r\n").encode())

    def read_until_idle(self, idle_gap=0.3, overall_timeout=15.0):
        chunks = []
        deadline = time.monotonic() + overall_timeout
        self.sock.settimeout(idle_gap)
        while time.monotonic() < deadline:
            try:
                data = self.sock.recv(65536)
                if not data:
                    break
                chunks.append(data)
            except socket.timeout:
                if chunks:
                    break
                continue
        return b"".join(chunks)


def read_reg_last_hex(client, addr, timeout=15.0):
    client.send(f"sysbus ReadDoubleWord {hex(addr)}")
    out = client.read_until_idle(idle_gap=0.3, overall_timeout=timeout)
    text = clean(out)
    matches = HEX_RE.findall(text)
    if len(matches) >= 2:
        return int(matches[-1], 16), text
    elif len(matches) == 1:
        return int(matches[0], 16), text
    raise RuntimeError(f"no hex value found reading {hex(addr)}: {text!r}")


def wait_for_port(host, port, deadline):
    while time.monotonic() < deadline:
        try:
            return socket.create_connection((host, port), timeout=1.0)
        except OSError:
            time.sleep(0.2)
    raise TimeoutError(f"port {port} never accepted a connection")


def write_char(client, byte_val):
    client.send(f"sysbus.uart1 WriteChar {byte_val}")
    client.read_until_idle(idle_gap=0.2, overall_timeout=8.0)


def main():
    monitor_port = 15090
    bridge_port = 15091
    uart_log = "/Users/probe/code/AltaVista/third_party/renode/M24_4b/handshake_fix_test_uart0.log"
    log_path = "/Users/probe/code/AltaVista/third_party/renode/M24_4b/handshake_fix_test.renode_log.txt"

    with open(log_path, "wb") as logf:
        proc = subprocess.Popen(
            [RENODE, "--disable-gui", "--hide-log", "-P", str(monitor_port)],
            stdin=subprocess.DEVNULL, stdout=logf, stderr=subprocess.STDOUT,
        )
        try:
            t0 = time.monotonic()
            mon = wait_for_port("127.0.0.1", monitor_port, t0 + 30.0)
            client = MonitorClient(mon)
            client.sock.settimeout(10.0)
            try:
                client.sock.recv(65536)
            except OSError:
                pass

            client.send(f"$bridgeport = {bridge_port}")
            client.read_until_idle()
            # Reuse the exact proven .resc (adds uart0 CreateFileBackend for the transcript).
            client.send(f'sysbus')  # no-op to sync
            client.read_until_idle()
            resc = ("/Users/probe/code/AltaVista/third_party/renode/M24_4b/"
                    "handshake_fix_test.resc")
            with open(resc, "w") as f:
                f.write(f'''# generated by handshake_fix_test.py
:name: av-m24-4b-handshake-fix-test
using sysbus
using sysbus.cluster0
using sysbus.cluster1
mach create "av-m24-4b-handshake-fix-test"
machine LoadPlatformDescription @/Users/probe/code/AltaVista/third_party/renode/platforms/cpus/zynqmp.repl
uart0 CreateFileBackend @{uart_log} true
emulation CreateServerSocketTerminal $bridgeport "uart1_bridge" false
connector Connect sysbus.uart1 uart1_bridge
macro reset
"""
    cluster0 ForEach IsHalted true
    cluster1 ForEach IsHalted true
    rpu0 IsHalted false
    sysbus LoadELF @/Users/probe/code/AltaVista/third_party/cfs/build-rtems_zynqmp/exe/cpu1/core-cpu1.exe cpu=rpu0
"""
runMacro $reset
''')
            client.send(f"include @{resc}")
            print("include reply:", clean(client.read_until_idle(overall_timeout=20.0))[:300])

            bridge_client = wait_for_port("127.0.0.1", bridge_port, time.monotonic() + 15.0)
            print("bridge client connected (captures guest's own UART1 TX, proven-working direction)")

            rxen_seen_at = None
            for i in range(60):
                client.send('emulation RunFor "0.05"')
                client.read_until_idle(overall_timeout=10.0)
                ctrl, _ = read_reg_last_hex(client, REG_CONTROL)
                if ctrl & CONTROL_RXEN:
                    rxen_seen_at = i
                    print(f"RXEN observed at step {i}")
                    break
            if rxen_seen_at is None:
                print("FAIL: RXEN never observed")
                return 2

            hello = build_hello_frame()
            print(f"injecting shim HELLO via WriteChar, {len(hello)} bytes: {hello.hex()}")
            for b in hello:
                write_char(client, b)

            # Run a bit more so the guest's read loop actually processes the injected bytes and
            # (if the fix works) replies with its own HELLO, then proceeds into handle_bind()'s
            # blocking read (which this test does not answer, by design -- proving the handshake
            # step specifically, not the whole bind/step loop).
            for i in range(20):
                client.send('emulation RunFor "0.05"')
                client.read_until_idle(overall_timeout=10.0)

            bridge_client.settimeout(2.0)
            guest_bytes = b""
            try:
                while True:
                    chunk = bridge_client.recv(4096)
                    if not chunk:
                        break
                    guest_bytes += chunk
            except socket.timeout:
                pass
            print(f"guest sent {len(guest_bytes)} bytes back: {guest_bytes.hex()}")
            print(f"guest HELLO reply matches shim's own HELLO bytes: {guest_bytes == hello}")

            with open(uart_log, "rb") as f:
                uart_content = f.read()
            handshake_failed = b"lockstep-local handshake failed" in uart_content
            bind_attempted = b"BIND failed" in uart_content
            entered_step_loop = b"bound, entering step loop" in uart_content
            print(f"UART0 'handshake failed' present: {handshake_failed}")
            print(f"UART0 'BIND failed' present: {bind_attempted}")
            print(f"UART0 'bound, entering step loop' present: {entered_step_loop}")

            # Print the tail of the UART0 log around the IO_LOCKSTEP lines for direct evidence.
            text = uart_content.decode(errors="replace")
            for line in text.splitlines():
                if "IO_LOCKSTEP" in line:
                    print("UART0:", line)

            bridge_client.close()
            client.send("quit")
            try:
                proc.wait(timeout=15.0)
            except subprocess.TimeoutExpired:
                proc.kill()
                proc.wait(timeout=15.0)

            success = (not handshake_failed) and (guest_bytes == hello)
            print(f"HANDSHAKE FIX RESULT: {'PASS' if success else 'FAIL'}")
            return 0 if success else 1
        finally:
            if proc.poll() is None:
                proc.kill()
                proc.wait(timeout=15.0)


if __name__ == "__main__":
    sys.exit(main())
